import type {LessonEs} from '../types';
/** Spanish words of the 11v11 lessons (chunk all), keyed by the English lesson id, in the English order (lib/site/lessons.ts). */
export const LESSONS_ES_11V11:Readonly<Record<string,LessonEs>>={
 'learn11_shape':{title:'Nuestros once: forma y tareas compartidas',concept:'Entiende al portero y cada línea, y luego ajusta el apoyo del mediocampo cuando un lateral avanza.',
  steps:['Tu equipo tiene once jugadores: un portero y diez jugadores de campo. Ataca el arco del fondo y protege el arco que está detrás de tu portero.','Aquí empezamos con cuatro defensas, tres mediocampistas y tres delanteros. El cuatro-tres-tres no cuenta al portero; el uno-cuatro-tres-tres sí lo cuenta.','El portero protege el arco y apoya los pases por detrás de la defensa. Se sigue ajustando a medida que se mueven el balón y la presión.','Dos defensas centrales protegen el centro. Los dos laterales defienden las bandas y pueden apoyar los ataques. Los cuatro defensas comparten el espacio en vez de cuidar puestos fijos.','Tres mediocampistas conectan las líneas. Aquí uno empieza más atrás, mientras dos ofrecen ángulos por delante. Sin el balón, ayudan a proteger el centro.','Dos extremos dan amplitud; el delantero centro da profundidad. Los delanteros también ayudan a defender. Estas tareas iniciales pueden cambiar cuando se mueven los compañeros.','Nuestro lateral izquierdo conduce el balón hacia delante para apoyar al extremo. Mira el espacio que deja atrás.','Los defensas centrales siguen protegiendo el centro. Un mediocampista puede ofrecer un ángulo de regreso y ayudar a cubrir detrás del lateral que avanza.','Eres el mediocampista más retrasado. ¿Dónde podrías ayudar detrás del lateral izquierdo?','Muévete detrás y por dentro del lateral. Seguir conectado le da otra opción al compañero que tiene el balón.','El lateral usa ese apoyo. Un mediocampista puede ayudar a un ataque sin correr por delante del balón.','Devuélvelo a través del defensa central. Toda la línea defensiva puede ayudar a llevar el balón a otro lado.','El otro defensa central recibe. El lateral izquierdo baja hacia la línea defensiva mientras el balón cruza.','El lateral derecho recibe. La siguiente tarea de apoyo está en este lado.','El lateral derecho conduce hacia delante. El extremo está más arriba, y el mediocampista cercano ya ofrece un ángulo por delante.','Sigues siendo el mediocampista más retrasado. ¿Dónde ayudarías ahora al lateral derecho?','Cruza por detrás del nuevo compañero con el balón. La formación te da una tarea inicial, pero el balón te ayuda a decidir dónde hacerla.','El pase de regreso te llega. Laterales, mediocampistas y defensas centrales trabajaron juntos en los dos lados.','Hay otras formaciones posibles. En el entrenamiento, prueba otro puesto e identifica la ayuda por delante, al lado y detrás de ti. Las relaciones útiles importan más que memorizar números.'],
  questions:[{q:'Eres el mediocampista más retrasado. ¿Dónde podrías ayudar detrás del lateral izquierdo?',options:['Unirte al mediocampista más adelantado','Ofrecer un ángulo detrás del lateral'],explain:'Una posición detrás y por dentro del lateral da un pase de regreso claro mientras los defensas centrales protegen el centro.'},
   {q:'Sigues siendo el mediocampista más retrasado. ¿Dónde ayudarías ahora al lateral derecho?',options:['Ofrecer un ángulo por dentro detrás del lateral derecho','Quedarte al lado del lateral izquierdo'],explain:'El balón y el lateral que avanza han cambiado de lado. Mueve tu apoyo mientras los defensas centrales siguen cubriendo por el centro.'},
   {q:'El balón ha cruzado hasta el otro defensa central. Toca adónde va ahora el lateral izquierdo.',options:['Bajar hacia la línea defensiva','Subir todavía más','Quedarse arriba donde terminó la conducción'],explain:'Como el balón se fue al otro lado, el lateral baja para que no quede un hueco en la línea defensiva.'},
   {q:'Ordena el movimiento hacia el nuevo lado, del primero al último.',options:['Los defensas centrales lo pasan al otro lado','El lateral se la devuelve al mediocampista','El mediocampista se mueve detrás del lateral izquierdo','El lateral derecho recibe en el otro lado'],explain:'Primero el apoyo por detrás, luego el pase de regreso, y después la línea defensiva lleva el balón al nuevo lado.'},
   {q:'El lateral derecho ha conducido mucho más arriba. Eres el mediocampista más retrasado. ¿Adónde te mueves para seguir conectado?',options:['Detrás y por dentro del lateral','Bien atrás en el centro, entre los defensas centrales','Arriba, al lado del extremo derecho'],explain:'Detrás y por dentro, das un pase de regreso seguro y cubres el espacio que dejó el lateral.'}]},
 'bld_11_throughlines':{title:'¿Puedes girar?',concept:'Mira antes de que llegue el balón. Gira cuando tengas espacio; usa tu apoyo cuando no lo tengas.',
  steps:['Has recibido en el mediocampo. Antes de girar, mira por encima del hombro.','El defensa se ha movido hacia un lado. Hay espacio justo delante.','Eres el mediocampista con el balón. ¿Hay espacio para girar hacia el arco?','Lleva el balón a ese espacio. Ahora puedes mirar hacia su arco.','El defensa más cercano se ha movido a tu derecha. El espacio justo delante está libre.','Vuelve a empezar. Veamos qué cambia cuando el defensa decide otra cosa.','Misma posición, otra presión. Este defensa se queda justo delante de ti.','Mira otra vez. ¿Qué harías con este primer toque?','Devuélvesela a tu compañero. Has conservado el balón y puedes buscar otro ángulo.','Mira antes de que llegue el balón. Gira cuando tengas espacio; usa tu apoyo cuando no lo tengas.'],
  questions:[{q:'Eres el mediocampista con el balón. ¿Hay espacio para girar hacia el arco?',options:['No, esta vez pasa atrás','Sí, gira hacia el espacio de delante'],explain:'El defensa más cercano se ha movido a tu derecha. El espacio justo delante está libre.'},
   {q:'Mira otra vez. ¿Qué harías con este primer toque?',options:['Devolverle el balón a tu apoyo','Girar directo hacia el arco'],explain:'El defensa está en el espacio hacia el que girarías. Tu compañero detrás de ti ofrece un pase claro.'},
   {q:'El defensa se ha movido a tu derecha. Toca el espacio hacia el que giras.',options:['Hacia atrás, a nuestro arco','Justo delante, hacia el arco','Hacia el defensa de la derecha'],explain:'El defensa dejó libre el centro, así que puedes girar y mirar hacia su arco.'},
   {q:'Recibes en el mediocampo. ¿Qué imagen te da espacio para girar hacia el arco?',options:['El defensa se mueve hacia un lado','El defensa presiona muy cerca','El defensa se queda delante'],explain:'El defensa se ha movido hacia un lado, así que el espacio justo delante está libre para girar.'},
   {q:'Esta vez el defensa se desliza a tu izquierda. ¿Qué debería hacer tu primer toque?',options:['Pasar atrás a tu apoyo','Girar hacia el espacio justo delante','Girar a la izquierda, hacia el defensa'],explain:'El centro vuelve a estar vacío, así que giras y miras hacia su arco.'}]},
 'bld_11_whenlong':{title:'Alrededor de la presión',concept:'La mejor ruta puede cambiar con un solo movimiento del defensa. Mira primero por dentro y luego por fuera.',
  steps:['Quieres avanzar, pero ese defensa puede tapar una línea de pase.','Se ha metido en el centro. Mira por fuera de él.','¿Qué pase supera a este defensa?','Juega por fuera del defensa. Tu compañero recibe mirando hacia la siguiente parte de la cancha.','El defensa tapa el pase por el centro. La ruta en diagonal a la izquierda sigue libre.','Vuelve a empezar. Veamos qué cambia cuando el defensa decide otra cosa.','Esta vez el defensa va hacia el compañero de la banda. Mira lo que ha dejado.','¿Dónde está la ruta libre hacia delante esta vez?','El centro se ha abierto. Pasa por dentro antes de que el defensa pueda volver.','La mejor ruta puede cambiar con un solo movimiento del defensa. Mira primero por dentro y luego por fuera.'],
  questions:[{q:'¿Qué pase supera a este defensa?',options:['El compañero justo delante','El compañero abierto a la izquierda'],explain:'El defensa tapa el pase por el centro. La ruta en diagonal a la izquierda sigue libre.'},
   {q:'¿Dónde está la ruta libre hacia delante esta vez?',options:['El compañero justo delante','El compañero abierto a la izquierda'],explain:'Al irse hacia la izquierda, el defensa se ha alejado de la línea de pase central.'},
   {q:'¿Verdadero o falso? Con el defensa en el centro, el pase justo delante es la ruta libre.',options:['Falso','Verdadero'],explain:'Es falso. El defensa está en la línea de pase central, así que jugamos por fuera de él, a la izquierda.'},
   {q:'Ordena la jugada alrededor de la presión, de la primera a la última.',options:['Mira dónde está el defensa','Pasa por fuera al compañero de la banda','Encuentra la línea libre por fuera de él','El compañero recibe mirando hacia delante'],explain:'Mira primero, encuentra la línea libre, pasa por fuera, y tu compañero puede mirar hacia delante.'},
   {q:'El defensa sigue tapando el centro, pero tu lateral derecho ha subido. ¿Qué pase supera al defensa?',options:['Por fuera, al lateral derecho','Atrás, al mediocampista defensivo','Directo al compañero delantero'],explain:'La línea de pase por la derecha está por fuera del defensa, así que el balón rodea la presión.'}]},
 'e_switch':{title:'Busca el lado libre',concept:'Cambia de juego para usar el espacio, no solo para mandar el balón al otro lado de la cancha.',
  steps:['Tienes apoyo en los dos lados. Mira adónde va la presión.','El defensa se desliza a la izquierda. Tu compañero de la derecha todavía tiene espacio.','¿Qué compañero puede recibir sin que el pase atraviese al defensa?','Mueve el balón a la derecha. El que recibe puede mirar hacia delante mientras la defensa cruza.','El defensa se ha ido a la izquierda y deja libre la línea de pase de la derecha.','Vuelve a empezar. Veamos qué cambia cuando el defensa decide otra cosa.','Esta vez la presión llega por el otro lado. Revisa otra vez las dos opciones.','¿Qué lado usarías en esta imagen?','Ahora usa el lado izquierdo. El mismo cambio de juego no funcionaría en las dos imágenes.','Cambia de juego para usar el espacio, no solo para mandar el balón al otro lado de la cancha.'],
  questions:[{q:'¿Qué compañero puede recibir sin que el pase atraviese al defensa?',options:['El compañero de la izquierda','El compañero de la derecha'],explain:'El defensa se ha ido a la izquierda y deja libre la línea de pase de la derecha.'},
   {q:'¿Qué lado usarías en esta imagen?',options:['El lado izquierdo','El lado derecho'],explain:'Ahora el defensa tapa la ruta de la derecha. El compañero de la izquierda está disponible.'},
   {q:'¿Verdadero o falso? El defensa se ha ido a la izquierda, así que la línea de pase a la derecha está libre.',options:['Falso','Verdadero'],explain:'Es verdadero. La presión se fue a la izquierda, así que el compañero de la derecha puede recibir y mirar hacia delante.'},
   {q:'¿Qué imagen muestra un cambio de juego que usa el espacio libre?',options:['Pase a la izquierda, defensa a la izquierda','Pase a la derecha, defensa a la izquierda','Pase a la derecha, defensa a la derecha'],explain:'El balón se aleja de la presión, así que el que recibe tiene tiempo para mirar hacia delante.'},
   {q:'El defensa sigue deslizándose a la izquierda, pero ahora tu mediocampista defensivo tiene el balón. ¿Qué pase usa el lado libre?',options:['Al otro lado, al mediocampista izquierdo','Corto, al mediocampista central','Arriba, al mediocampista derecho'],explain:'El lado derecho está lejos de la presión, así que el que recibe puede girar y mirar hacia delante.'}]},
 'e_thirdman':{title:'Usa al siguiente compañero',concept:'Un tercer hombre ayuda cuando el pase directo está tapado. No necesitas un pase de más cuando ya está libre.',
  steps:['El compañero de delante está marcado. Un compañero cercano puede ayudarte a hacerle llegar el balón.','El defensa se queda en la línea de pase directa. Busca la conexión más corta.','¿Cuál es el primer pase útil aquí?','Busca primero al compañero de la izquierda. Desde ahí, el delantero está en otro ángulo de pase.','El compañero de la izquierda pasa. Un tercer hombre recibe por detrás del defensa.','Dos pases claros llevaron el balón alrededor de la ruta tapada.','Vuelve al compañero de la izquierda para comparar con la siguiente imagen.','El compañero de la izquierda tiene un primer pase claro y otro ángulo hacia el delantero.','Vuelve a empezar. Veamos qué cambia cuando el defensa decide otra cosa.','Esta vez el defensa sigue a esa opción corta. Revisa otra vez la ruta directa.','¿Todavía necesitas el pase de más?','Juega directo al compañero delantero. El defensa ha dejado esa línea de pase.','Un tercer hombre ayuda cuando el pase directo está tapado. No necesitas un pase de más cuando ya está libre.'],
  questions:[{q:'¿Cuál es el primer pase útil aquí?',options:['Pasar directo al compañero delantero','Pasar primero al compañero de la izquierda'],explain:'El compañero de la izquierda tiene un primer pase claro y otro ángulo hacia el delantero.'},
   {q:'¿Todavía necesitas el pase de más?',options:['No, pasa directo al compañero delantero','Sí, pasa primero al compañero de la izquierda'],explain:'El defensa salió de la línea de pase directa. Puedes conectar con el delantero enseguida.'},
   {q:'El compañero de la izquierda ha recibido tu pase. ¿Qué debería pasar ahora?',options:['Regatear hacia el defensa','Pasar al delantero','Devolvértela directo a ti'],explain:'Desde la izquierda, el delantero está en otro ángulo, así que el tercer hombre recibe por detrás del defensa.'},
   {q:'La línea de pase directa al delantero está tapada. ¿Qué imagen muestra la ruta del tercer hombre?',options:['Primero el compañero de la izquierda, luego el delantero','Pase atrás al mediocampista más retrasado','Pase directo al delantero'],explain:'Dos pases claros llevan el balón alrededor del defensa hasta el tercer hombre.'},
   {q:'Ahora el defensa está entre el compañero de la izquierda y el delantero. ¿Cuál es el mejor pase?',options:['Atrás, al mediocampista más retrasado','Directo al delantero','Primero al compañero de la izquierda'],explain:'La línea de pase directa está libre, así que no necesitamos un pase de más.'}]},
 'learn11_cutback':{title:'Mira detrás de los defensas',concept:'Encuentra al compañero y luego revisa la ruta. Un centro atrás solo sirve cuando ese pase está libre.',
  steps:['Has llegado al costado del área. Echa un vistazo rápido antes de meter el balón.','El defensa sigue al compañero que corre hacia el arco. Alguien espera detrás de él.','¿Qué pase encuentra al compañero que está detrás del defensa?','Tira el balón hacia atrás al compañero que espera. Él puede elegir su siguiente toque.','El defensa ha seguido la carrera hacia el arco y deja libre la línea del centro atrás.','Vuelve a empezar. Veamos qué cambia cuando el defensa decide otra cosa.','Esta vez el defensa baja hacia el centro atrás. No le mandes el balón a él.','¿Qué harías ahora desde el costado del área?','Quédate con el balón usando a tu apoyo por la banda. No hace falta forzar un centro a una zona llena de jugadores.','Encuentra al compañero y luego revisa la ruta. Un centro atrás solo sirve cuando ese pase está libre.'],
  questions:[{q:'¿Qué pase encuentra al compañero que está detrás del defensa?',options:['Pase atrás al mediocampista que espera','Pase al compañero que corre cerca del arco'],explain:'El defensa ha seguido la carrera hacia el arco y deja libre la línea del centro atrás.'},
   {q:'¿Qué harías ahora desde el costado del área?',options:['Pasar atrás al mediocampista de dentro','Pasar al apoyo por la banda'],explain:'Ahora el defensa está en la línea del centro atrás. El compañero que apoya ofrece una ruta clara para conservar el balón.'},
   {q:'¿Verdadero o falso? El defensa ha bajado hacia el centro atrás, así que tirar el balón hacia atrás sigue siendo un buen pase.',options:['Falso','Verdadero'],explain:'Es falso. Ahora el defensa está en la línea del centro atrás, así que nos quedamos con el balón usando a nuestro apoyo.'},
   {q:'Ordena el centro atrás, del primero al último.',options:['El defensa sigue al que corre hacia el arco','Levanta la vista en el costado del área','Tira el balón atrás al compañero que espera','Se abre la línea detrás del defensa'],explain:'Mira primero, ve cómo el defensa sigue la carrera, y tira el balón atrás a la línea que dejó.'},
   {q:'El defensa sigue al que corre, y el compañero que espera se movió hacia dentro. ¿Qué pase crea la mejor ocasión?',options:['Al otro lado, al que corre cerca del arco','Atrás por la banda, a tu apoyo','Centro atrás al compañero que espera'],explain:'El defensa se fue con el que corre, así que la línea del centro atrás hacia el compañero está libre.'}]},
 'def_11_pressurecover':{title:'¿Quién va y quién ayuda?',concept:'Decidan juntos. Un jugador presiona el balón; otro cuida el siguiente peligro.',
  steps:['Ellos tienen el balón. Si los dos se lanzan, ¿quién cuida el espacio de atrás?','Tu compañero se acerca al balón. Quédate detrás de él, listo para un pase o un regate.','Eres el mediocampista más retrasado. ¿Qué ayuda aquí a tu compañero?','Nuestro mediocampista más cercano mantiene la presión mientras el otro se mueve para cubrir. Ahora uno de nosotros presiona el balón y otro cubre por detrás.','Su compañero con el balón prueba la presión conduciendo un poco. Nuestro mediocampista más cercano se mueve con el balón, y el que cubre mantiene una segunda línea defensiva.','Vuelve a colocar a los dos mediocampistas. Sus distancias al rival con el balón decidirán quién presiona y quién cubre.','En esta imagen tu compañero está más lejos. Tú eres quien puede frenar al rival con el balón.','Eres el mediocampista central. ¿Cuál es tu tarea esta vez?','Ahora nuestro mediocampista central está más cerca y presiona. Nuestro otro mediocampista cubre por detrás en vez de perseguir el mismo balón.','Su compañero con el balón vuelve a moverse. Nuestro mediocampista más cercano lo sigue sin cruzarse en el camino del compañero que cubre. La presión y la cobertura siguen conectadas.'],
  questions:[{q:'Eres el mediocampista más retrasado. ¿Qué ayuda aquí a tu compañero?',options:['Quedarte detrás del compañero que presiona','Unirte a la presión junto al compañero'],explain:'Tu compañero ya es el más cercano al rival con el balón. Quedarte detrás de él protege la siguiente acción.'},
   {q:'Eres el mediocampista central. ¿Cuál es tu tarea esta vez?',options:['Bajar a una posición de cobertura más atrás','Acercarte al rival con el balón'],explain:'Ahora eres el defensor más cercano. Puedes frenar al rival con el balón mientras tu compañero te cubre.'},
   {q:'El rival con el balón conduce un poco. ¿Qué hacen después nuestros dos mediocampistas?',options:['Los dos persiguen juntos el balón','Los dos bajan con los defensas','El cercano se mueve con el balón; el otro sigue cubriendo'],explain:'La presión sigue sobre el balón mientras la cobertura mantiene una segunda línea detrás.'},
   {q:'¿Qué imagen muestra la presión y la cobertura trabajando juntas?',options:['Los dos mediocampistas en el balón','Los dos mediocampistas se quedan atrás','Uno presiona, otro cubre por detrás'],explain:'Uno frena al rival con el balón, y el otro protege el espacio de atrás para el siguiente peligro.'},
   {q:'Esta vez el mediocampista central está más cerca y presiona. Eres el otro mediocampista. ¿Adónde vas?',options:['Detrás del que presiona, cubriendo','A unirte a la presión en el balón','A quedarte abierto en la banda'],explain:'Detrás del que presiona, cubres el siguiente pase o regate en vez de perseguir el mismo balón.'}]},
 'def_11_shift':{title:'Muévanse juntos hacia el lado',concept:'Sigan el peligro como grupo. No dejen un hueco grande para el siguiente pase.',
  steps:['El balón está en la banda. Tu equipo tiene que moverse hacia ese lado sin dejar vacío el centro.','El rival con el balón se va más a la izquierda. Muévete hacia ese lado, pero deja a un compañero entre el balón y el arco.','¿Hacia dónde debería ajustarse este grupo de mediocampistas?','Unos pasos a la izquierda mantienen conectado a tu equipo. El centro sigue cubierto.','El balón está a la izquierda, pero el espacio delante del arco todavía hay que protegerlo.','Vuelve a llevar al grupo al centro y luego compara el peligro en el otro lado.','El balón se va al otro lado. Gira, mira a tus compañeros y muévanse juntos.','¿Adónde debería moverse ahora el grupo?','Muévanse juntos a la derecha. El jugador del lado lejano se cierra hacia dentro en vez de quedarse solo en la banda.','Sigan el peligro como grupo. No dejen un hueco grande para el siguiente pase.'],
  questions:[{q:'¿Hacia dónde debería ajustarse este grupo de mediocampistas?',options:['Moverse unos pasos hacia la izquierda','Moverse hasta la línea de banda izquierda'],explain:'El balón está a la izquierda, pero el espacio delante del arco todavía hay que protegerlo.'},
   {q:'¿Adónde debería moverse ahora el grupo?',options:['Hacia el lado izquierdo','Hacia el lado derecho'],explain:'El balón se ha ido a la derecha. Moverse en grupo cierra ese lado sin abrir un gran hueco en el centro.'},
   {q:'¿Verdadero o falso? Con el balón a la izquierda, el mediocampo se mueve unos pasos pero sigue cubriendo el centro.',options:['Falso','Verdadero'],explain:'Es verdadero. Un movimiento corto mantiene conectado al grupo, así que un pase hacia dentro todavía se encuentra con un mediocampista.'},
   {q:'El balón ha cambiado a la derecha. ¿Qué forma del mediocampo protege contra el siguiente pase?',options:['Los tres mediocampistas van al balón','El mediocampo se mueve a la derecha en grupo','El mediocampo se queda en sus puestos centrales'],explain:'Moverse juntos pone ayuda cerca del balón mientras el centro sigue cubierto.'},
   {q:'El balón está a la derecha, pero tu mediocampista izquierdo se quedó abierto. Arrástralo adonde ayuda.',options:['Cruzar corriendo hasta el balón','Quedarse abierto en la línea de banda izquierda','Cerrarse hacia el centro'],explain:'Al cerrarse, tapa el hueco al lado del mediocampista central, así que un pase hacia dentro está cubierto.'}]},
 'trn_11_recover':{title:'¿Podemos recuperarlo?',concept:'Ve a disputar el balón cuando se pueda ganar. Si la ocasión ya pasó, vuelve y protege tu arco.',
  steps:['Acabas de perder el balón. Mira al rival y a los compañeros que pueden ayudar.','El rival con el balón está lo bastante cerca para acercarte, y un compañero puede cubrir detrás de ti.','Eres el mediocampista más cercano. ¿Qué encaja en esta imagen?','Acércate sin lanzarte. Tu compañero se queda detrás de ti por si el balón se escapa.','Puedes acercarte al rival con el balón mientras un compañero protege el espacio detrás de ti.','Vuelve a colocar a los mediocampistas para comparar con un rival que ya escapó de la presión.','Esta vez el rival conserva el balón y ya te ha superado.','El rival te ha pasado. ¿Adónde debería llevarte tu siguiente carrera?','Gira y recupera hacia el arco. Estás volviendo a una posición desde la que puedes ayudar.','Ve a disputar el balón cuando se pueda ganar. Si la ocasión ya pasó, vuelve y protege tu arco.'],
  questions:[{q:'Eres el mediocampista más cercano. ¿Qué encaja en esta imagen?',options:['Bajar a una posición más cerca de nuestro arco','Acercarte al rival con el balón'],explain:'Puedes acercarte al rival con el balón mientras un compañero protege el espacio detrás de ti.'},
   {q:'El rival te ha pasado. ¿Adónde debería llevarte tu siguiente carrera?',options:['Perseguir al rival por detrás','Recuperar por el lado del arco del rival con el balón'],explain:'Recuperar por el lado del arco ayuda a proteger el siguiente ataque. Perseguir por el lado equivocado deja más espacio delante del rival con el balón.'},
   {q:'¿Verdadero o falso? El rival con el balón está cerca, así que el mediocampista más cercano debería lanzarse a hacer una entrada enseguida.',options:['Falso','Verdadero'],explain:'Es falso. Acércate sin lanzarte, para que el rival no pueda simplemente pasarte.'},
   {q:'Ordena la decisión después de perder el balón, de la primera a la última.',options:['Bastante cerca y con cobertura: acércate','Mira al rival con el balón y a tus ayudas','El rival con el balón se te escapa','Gira y recupera hacia el arco'],explain:'Mira primero, presiona mientras el balón se pueda ganar, y recupera cuando el rival se escape.'},
   {q:'Ahora el rival con el balón se te escapa por la derecha. Toca dónde debería terminar tu carrera de recuperación.',options:['Persiguiendo detrás del rival','En el lado del arco del rival con el balón','Arriba, cerca de la línea media'],explain:'Recuperar por el lado del arco te pone entre el balón y el arco, así que puedes volver a ayudar.'},
   {q:'El rival con el balón da un toque largo, y el balón rueda hacia ti. ¿Qué haces?',options:['Entrar y ganar el balón','Girar y correr hacia el arco','Esperar y mirar al rival'],explain:'El balón está suelto y cerca de ti, así que este es el momento de recuperarlo.'}]},
 'trn_11_restdefense':{title:'Deja a alguien para ayudar',concept:'Unirse a un ataque es una decisión de equipo. Revisa quién cubrirá el espacio que dejas.',
  steps:['Tu equipo está atacando. Antes de sumarte, mira quién se queda detrás del balón.','Dos compañeros ya están arriba. El espacio detrás de ellos todavía te necesita.','Eres el mediocampista central detrás del balón. ¿Qué es útil aquí?','Quédate detrás del ataque. Eres una opción de pase atrás y la primera ayuda si se pierde el balón.','Los otros mediocampistas ya están por delante. Quedarte detrás de ellos da cobertura y un pase de regreso.','Devuelve el balón y compara quién protege ahora el espacio detrás del ataque.','Esta vez otro compañero ocupa esa posición más retrasada. Puedes ofrecer un ángulo más adelante.','Con un compañero cubriendo detrás de ti, ¿qué puedes ofrecer ahora?','Muévete a un ángulo de apoyo útil. Tu compañero más retrasado cuida el espacio de atrás.','Unirse a un ataque es una decisión de equipo. Revisa quién cubrirá el espacio que dejas.'],
  questions:[{q:'Eres el mediocampista central detrás del balón. ¿Qué es útil aquí?',options:['Unirte arriba a los dos compañeros','Quedarte disponible detrás del ataque'],explain:'Los otros mediocampistas ya están por delante. Quedarte detrás de ellos da cobertura y un pase de regreso.'},
   {q:'Con un compañero cubriendo detrás de ti, ¿qué puedes ofrecer ahora?',options:['Bajar al lado del compañero más retrasado','Ofrecer un ángulo más adelante'],explain:'Ahora tu compañero da la cobertura de atrás. Moverte a otro ángulo le da otra opción al compañero con el balón.'},
   {q:'Dos compañeros ya están arriba. Arrastra al mediocampista central adonde más ayuda.',options:['Bajar a la línea defensiva','Quedarse justo detrás del ataque','Unirse al ataque cerca del balón'],explain:'Quedarse detrás del ataque da un pase de regreso y una primera línea de defensa si se pierde el balón.'},
   {q:'¿Verdadero o falso? En esta imagen, nadie protege el espacio detrás del ataque.',options:['Falso','Verdadero'],explain:'Es falso. El mediocampista defensivo se queda atrás, así que el mediocampista central podía subir.'},
   {q:'Ahora el ataque va por la derecha. ¿Qué imagen deja una ayuda detrás del balón?',options:['El mediocampista baja a la línea defensiva','El mediocampista se queda detrás del ataque','El mediocampista se une al ataque'],explain:'Quedarse detrás del balón da un pase de regreso seguro y frena un contraataque rápido.'}]},
 'learn11_restart':{title:'Un saque de meta necesita dos opciones',concept:'Dale opciones a tu portero. Lee al rival antes de decidir adónde va el pase.',
  steps:['El portero tiene un saque de meta. Dos compañeros ofrecen ángulos diferentes.','El rival cierra la ruta de la izquierda. Mira a la derecha.','¿Qué pase corto tiene la ruta más clara?','Juega a la derecha. Ese compañero puede abrirse hacia la cancha.','El rival tapa la ruta de la izquierda. El portero puede llegar al compañero de la derecha con un pase raso.','Devuélvele el balón al portero. Esta es una nueva imagen de saque de meta, con presión en el otro lado.','Esta vez el rival se mueve a la derecha. Revisa otra vez al compañero de la izquierda.','¿Qué compañero puede recibir esta vez?','Esta vez usa la opción de la izquierda. El rival ha dejado libre esa ruta.','Dale opciones a tu portero. Lee al rival antes de decidir adónde va el pase.'],
  questions:[{q:'¿Qué pase corto tiene la ruta más clara?',options:['Pase al compañero de la izquierda','Pase al compañero de la derecha'],explain:'El rival tapa la ruta de la izquierda. El portero puede llegar al compañero de la derecha con un pase raso.'},
   {q:'¿Qué compañero puede recibir esta vez?',options:['El compañero de la izquierda','El compañero de la derecha'],explain:'El rival se ha movido a la derecha. La ruta hacia el compañero de la izquierda ahora está libre.'},
   {q:'El portero pasa al compañero libre de la derecha. ¿Qué debería hacer ese compañero ahora?',options:['Regatear hacia nuestra propia línea de meta','Abrirse y mirar hacia la cancha','Devolvérsela directo al portero'],explain:'Abrirse hacia la cancha deja que el que recibe vea los pases hacia delante y haga avanzar el balón.'},
   {q:'Ordena el saque de meta, del primer paso al último.',options:['El portero pasa por la ruta libre','El rival cierra una de las rutas','El que recibe controla y gira hacia delante','Dos compañeros ofrecen ángulos diferentes'],explain:'Dos ángulos dan opciones; el rival solo puede cerrar uno, así que el portero usa el otro.'},
   {q:'Ahora el rival se mete en el centro. ¿Qué pase de saque de meta tiene la ruta libre?',options:['Saque largo al delantero centro','Pase al compañero de la derecha','Pase corto por el centro'],explain:'El rival se ha movido hacia dentro, así que la ruta por abajo hacia el compañero de la derecha está libre.'}]},
 'gap11_runoncue':{title:'Corre cuando el pase es posible',concept:'Corre cuando el pase es posible, y sal en el momento del pase para quedar habilitado (Regla 11). Si el pase está tapado, primero acércate hacia el balón.',
  steps:['Eres el delantero centro. El espacio detrás de la línea defensiva solo sirve si tu compañero puede llegar a él.','El mediocampista tiene el balón, pero un rival tapa el pase directo hacia delante.','¿Qué movimiento le da a este mediocampista un pase disponible?','Acércate en diagonal, alejándote del rival que tapa.','El mediocampista conecta rodeando al rival que tapa. Puedes ayudar a que el ataque siga en movimiento.','Devuelve el balón. Mira otra vez antes de hacer la siguiente carrera.','El delantero centro vuelve a colocarse delante de la línea defensiva mientras el rival que tapa se mueve a la izquierda.','El mediocampista tiene una ruta en diagonal clara hacia el pasillo izquierdo. Fíjate en el momento del pase.','¿Qué carrera ataca el pasillo libre cuando el mediocampista suelta el pase?','Arranca cuando el mediocampista suelta el pase. Encuentra el balón en el pasillo izquierdo.','El delantero centro recibe detrás de la línea. La carrera y el pase han funcionado juntos.','Revisa la ruta y a tu compañero antes de correr. Conecta cuando te tapen; ataca el pasillo cuando el pase sea posible.'],
  questions:[{q:'¿Qué movimiento le da a este mediocampista un pase disponible?',options:['Acercarte en diagonal hacia el balón','Correr directo detrás de la línea defensiva'],explain:'Acercarte en diagonal abre una ruta alrededor del rival que tapa. Le das al mediocampista un pase que ya puede llegarte.'},
   {q:'¿Qué carrera ataca el pasillo libre cuando el mediocampista suelta el pase?',options:['Volver a acercarte hacia el balón','Correr en diagonal hacia el pasillo izquierdo'],explain:'Sal desde delante de la línea defensiva cuando se suelta el pase. La carrera en diagonal encuentra el balón detrás de los defensas.'},
   {q:'Ordena los movimientos del delantero centro en esta lección, del primero al último.',options:['Conecta rodeando al rival que tapa','El pase está tapado, así que acércate alejándote de él','Corre cuando el mediocampista suelta el pase','El rival que tapa se va a la izquierda y se abre el pasillo'],explain:'Acércate lejos del rival que tapa, conecta, y solo cuando se abra el pasillo, corre en el momento del pase.'},
   {q:'¿Verdadero o falso? El delantero centro debería arrancar la carrera al pasillo cuando el mediocampista suelta el pase.',options:['Falso','Verdadero'],explain:'Es verdadero. Correr en el momento del pase te hace encontrar el balón en el pasillo.'},
   {q:'Ahora el rival que tapa está a la derecha. Toca hacia dónde debería acercarse el delantero centro para conectar.',options:['Acercarse en diagonal a la izquierda','Acercarse en diagonal a la derecha','Correr directo por detrás'],explain:'Acercarse lejos del rival que tapa, hacia la izquierda, abre una línea de pase libre desde el mediocampista.'}]},
 'exp11_checking8':{title:'4-3-3 contra 5-3-2: el ocho que se acerca',concept:'Cuando sus carrileros tapan a tus laterales, un ocho se acerca en corto para quedar libre. Si un defensa sigue al ocho, pasa al lateral.',
  steps:['Tus tres delanteros se quedan arriba y habilitados, cada uno ocupando a un defensa central de la línea de cinco del rival.','Los dos laterales ofrecen amplitud por debajo de ellos. Los carrileros del equipo Azul pueden tapar esas rutas por la banda.','Tus tres mediocampistas necesitan carriles diferentes contra el mediocampo Azul. El seis es tu mediocampista más retrasado. Un ocho juega más arriba y puede acercarse en corto a otro carril.','El ocho izquierdo se acerca por debajo de la línea del mediocampo. El seis se mantiene separado, mientras el carrilero tapa el pase de tu defensa central al lateral.','El carrilero tapa el pase a la banda. ¿Qué compañero ofrece una ruta clara por debajo del mediocampo?','El ocho recibe por debajo del mediocampo. El seis mantiene otro carril y le da al que recibe otra conexión por dentro.','El ocho devuelve el balón. Esta vez el mediocampista Azul sigue al ocho que se acerca y el carrilero baja hacia tu extremo, dejando el carril de la banda original de tu lateral.','El mediocampista sigue a tu ocho y el carrilero ha bajado. ¿Qué pase encaja en la nueva imagen?','El lateral recibe en el carril de la banda que quedó libre. El ocho arrastra hacia dentro al mediocampista que lo sigue y aleja esa presión del que recibe.'],
  questions:[{q:'El carrilero tapa el pase a la banda. ¿Qué compañero ofrece una ruta clara por debajo del mediocampo?',options:['Buscar al ocho que se acerca','Forzar el pase al lateral'],explain:'El ocho se ha acercado por debajo de la línea del mediocampo. El seis ofrece otro carril y los delanteros mantienen ocupados a los tres de atrás.'},
   {q:'El mediocampista sigue a tu ocho y el carrilero ha bajado. ¿Qué pase encaja en la nueva imagen?',options:['Forzar el pase al ocho marcado','Soltar el pase al lateral'],explain:'El carrilero ha dejado la línea de pase original. Ahora el lateral tiene espacio para recibir y avanzar.'},
   {q:'El carrilero Azul tapa a tu lateral. Toca adónde se acerca el ocho izquierdo para ofrecer un pase claro.',options:['Acercarse en corto por debajo de la línea del mediocampo','Abrirse hasta la línea de banda','Quedarse arriba, detrás del mediocampista Azul'],explain:'Acercarse por debajo de la línea del mediocampo Azul abre una ruta clara desde el defensa central.'},
   {q:'¿Verdadero o falso? Aquí el seis debería meterse en el mismo carril que el ocho para ayudarlo.',options:['Falso','Verdadero'],explain:'Es falso. El seis mantiene otro carril y le da al ocho otra conexión por dentro.'},
   {q:'¿Qué imagen muestra el momento de pasar al lateral?',options:['El carrilero bajó y siguieron al ocho','El carrilero en la banda y siguieron al ocho','El carrilero en la banda y el ocho libre'],explain:'El carrilero ha bajado y el ocho arrastra a su marca hacia dentro, así que el lateral está libre.'}]},
 'exp11_insidefullback':{title:'4-3-3: ¿lateral por dentro o por fuera?',concept:'Ocupa el carril que nadie tiene: con el extremo abierto, el lateral se mete por dentro; con el extremo por dentro, el lateral se abre.',
  steps:['Tus dos defensas centrales y el lateral del lado lejano forman un grupo de tres más atrás, detrás del ataque.','El seis, tu mediocampista de contención, necesita otro ángulo de apoyo. El lateral del lado cercano puede meterse por dentro para ser esa segunda ayuda.','Tus dos mediocampistas más adelantados se llaman ochos. Con los dos extremos y el delantero centro, ocupan cinco carriles de ataque. El extremo ya da la amplitud en el lado cercano.','El extremo izquierdo ya está abierto y el ocho izquierdo se queda arriba. Al lado del seis hay otro carril de apoyo por dentro para el lateral.','Tu extremo está abierto y los dos ochos están arriba. ¿Dónde aporta el lateral otro carril de apoyo?','El lateral llega por dentro con espacio al lado del seis. El extremo mantiene el carril de fuera y el ocho se queda más arriba, así que ninguna de estas tres tareas se repite.','Ahora el extremo se mete por dentro y el ocho baja al lado del seis. Esos compañeros ya dan apoyo por el centro; el carril de fuera está vacío.','Ahora el ocho ayuda al seis y tu extremo está por dentro. ¿Qué ruta recupera un carril que falta?','El lateral recupera el carril de fuera. El ocho hace de ayuda por dentro y el extremo sigue más arriba, entre defensas. Los papeles cambian sin perder un carril útil.'],
  questions:[{q:'Tu extremo está abierto y los dos ochos están arriba. ¿Dónde aporta el lateral otro carril de apoyo?',options:['Meterse por dentro al lado del seis','Correr al lado del extremo abierto'],explain:'Así se crea otra ayuda por dentro. El lateral del lado lejano y los dos defensas centrales se quedan atrás, mientras cinco compañeros ocupan la línea de ataque.'},
   {q:'Ahora el ocho ayuda al seis y tu extremo está por dentro. ¿Qué ruta recupera un carril que falta?',options:['Abrirse al carril izquierdo','Quedarse al lado de las ayudas del centro'],explain:'El extremo ha dejado el carril de fuera. Puedes recuperar la amplitud mientras el ocho hace tu tarea por dentro.'},
   {q:'Tu extremo está abierto y los ochos están arriba. Arrastra al lateral izquierdo a un carril que nadie ocupa.',options:['Detrás del seis, cerca de los defensas centrales','Por dentro, al lado del seis','Abierto, por debajo del extremo'],explain:'Al lado del seis, el lateral se convierte en una segunda ayuda sin repetir el carril del extremo.'},
   {q:'¿Verdadero o falso? En esta imagen, nadie ocupa el carril de fuera de la izquierda.',options:['Falso','Verdadero'],explain:'Es verdadero. El extremo se metió por dentro y el ocho bajó, así que el lateral tiene que recuperar esa amplitud.'},
   {q:'La misma idea por la derecha: extremo abierto, ocho arriba. ¿Qué imagen le da al lateral derecho un carril propio?',options:['Lateral detrás del seis','Lateral por dentro, al lado del seis','Lateral abierto, por debajo del extremo'],explain:'Con el extremo abierto y el ocho arriba, el carril libre está por dentro, junto al seis.'}]},
 'exp11_safetyfive':{title:'Cinco arriba, cinco de seguridad: dos líneas',concept:'Mientras cinco atacan, dos mediocampistas hacen de pantalla y tres defensas se quedan atrás. Si un pase supera la pantalla, recupera por dentro.',
  steps:['Cinco compañeros atacan en carriles separados: dos por fuera, dos por dentro y el delantero centro.','Detrás de ellos, dos mediocampistas hacen de pantalla ante los pases hacia los receptores adelantados del rival. Protegen el espacio delante de los defensas.','Tres defensas más atrás se encargan de esos tres receptores adelantados. Las pantallas y los defensas deben seguir siendo dos líneas conectadas.','La pantalla izquierda puede cerrar la ruta hacia el receptor de la banda. El defensa más cercano se queda detrás de esa amenaza, mientras la otra pantalla protege el centro.','Tu equipo ya tiene cinco atacantes arriba. ¿Qué posición protege el pase hacia el receptor cercano?','El mediocampista izquierdo tapa la ruta hacia el receptor cercano. Su compañero mantiene el carril central, y los defensas de atrás siguen conectados detrás de ellos.','El ataque pierde un pase por dentro. El equipo Azul lo controla en el centro y el receptor cercano se abre más, lo que cambia el carril alrededor de tu pantalla.','Azul pasa por fuera de la pantalla al receptor de la banda. El defensa más cercano se acerca desde dentro. Tu mediocampista ahora está detrás del balón y tiene que recuperar.','El pase ha superado tu pantalla. ¿Dónde puedes volver a armar la protección delante de los defensas de atrás?','El mediocampista recupera por dentro del defensa que temporiza. La otra pantalla cierra el carril central, mientras los otros dos defensas de atrás se encargan de las demás amenazas adelantadas.'],
  questions:[{q:'Tu equipo ya tiene cinco atacantes arriba. ¿Qué posición protege el pase hacia el receptor cercano?',options:['Unirte a la línea de ataque','Hacer de pantalla delante de los tres de atrás'],explain:'Puedes cerrar el carril del receptor cercano mientras la otra pantalla protege el centro y los tres de atrás se encargan de los atacantes adelantados.'},
   {q:'El pase ha superado tu pantalla. ¿Dónde puedes volver a armar la protección delante de los defensas de atrás?',options:['Perseguir al que pasó','Recuperar por dentro del defensa que temporiza'],explain:'El defensa más cercano temporiza ante el rival con el balón en la banda. Recuperar por dentro protege el siguiente pase por el centro mientras la otra pantalla cierra.'},
   {q:'¿Verdadero o falso? Tu lateral izquierdo se acerca al receptor de la banda, así que el seis debería dejar el centro para ayudar.',options:['Falso','Verdadero'],explain:'Es falso. El seis cierra el carril central, así que los defensas de atrás mantienen una pantalla delante.'},
   {q:'Azul supera tu pantalla. Ordena estos momentos, del primero al último.',options:['Azul pasa por fuera de la pantalla a la banda','Azul gana un pase suelto por dentro','La pantalla izquierda tapa al receptor mientras atacamos','El mediocampista recupera por dentro del defensa que temporiza'],explain:'La pantalla está colocada mientras atacamos, Azul gana el balón, la rodea, y tú recuperas.'},
   {q:'Ahora Azul rodea tu pantalla derecha. Arrastra al seis para volver a armar la protección delante de los defensas.',options:['Perseguir al que pasó','Unirse al defensa en el balón','Recuperar por dentro del defensa que temporiza'],explain:'El seis vuelve a armar la pantalla por dentro, así que tu defensa puede temporizar ante el extremo con cobertura.'}]},
 'exp11_diamondjump':{title:'Rombo contra 4-3-3: ¿quién cierra al lateral?',concept:'Cierra a su lateral con el jugador libre más cercano, pero nunca dejes abierto el centro de tu rombo.',
  steps:['Tu rombo en el mediocampo tiene un mediocampista de contención llamado el seis, dos mediocampistas de los lados y un mediocampista más adelantado llamado el diez. Comparten el centro y la presión en la banda.','Dos delanteros trabajan contra los defensas centrales mientras el diez tapa al seis del equipo Azul. Esto puede dejar a un lateral disponible por fuera del rombo.','Tu línea de cuatro se encarga de los tres delanteros Azules. El lateral del lado cercano no puede simplemente dejar al extremo para arreglar cada presión del mediocampo.','Azul llega a su lateral izquierdo. Tu diez sigue tapando a su seis y tu lateral izquierdo tiene a un extremo. Ahora el ocho izquierdo puede cerrar al que recibe en la banda.','El diez sigue tapando a su seis y tu lateral izquierdo tiene a un extremo. ¿A quién puedes acercarte?','El ocho izquierdo se acerca al lateral. El diez mantiene la pantalla central y el ocho del lado lejano se cierra al lado del seis, manteniendo la cobertura detrás de la presión.','El seis Azul sale de la pantalla de tu diez. Tu delantero cercano se encarga ahora de presionar al lateral, así que el ocho tiene que proteger el carril por dentro que se acaba de abrir.','Tu delantero puede presionar al lateral, pero su seis se ha escapado del diez. ¿Qué carrera termina el trabajo?','El ocho vuelve por dentro mientras el delantero presiona al lateral. El seis y el ocho del lado lejano siguen conectados detrás, manteniendo la cobertura por dentro detrás de la presión en la banda.'],
  questions:[{q:'El diez sigue tapando a su seis y tu lateral izquierdo tiene a un extremo. ¿A quién puedes acercarte?',options:['Cerrar al lateral','Bajar al lado de tu seis'],explain:'La pantalla central sigue intacta. Tu lateral puede quedarse con el extremo mientras tú presionas al que recibe en la banda y el ocho del lado lejano se cierra.'},
   {q:'Tu delantero puede presionar al lateral, pero su seis se ha escapado del diez. ¿Qué carrera termina el trabajo?',options:['Unirte a la presión del delantero','Recuperar hacia el carril de dentro'],explain:'Ahora el delantero se encarga del balón. Recuperar por dentro te pone entre su seis libre y la siguiente conexión hacia delante.'},
   {q:'Azul llega a su lateral izquierdo, y tu lateral izquierdo tiene a un extremo. ¿Qué hace después tu lateral izquierdo?',options:['Sale corriendo a presionar al lateral','Se queda en el lado del arco del extremo Azul','Se mete por dentro para tapar al seis'],explain:'La línea de cuatro tiene que encargarse de los tres delanteros Azules, así que el lateral izquierdo se queda con el extremo.'},
   {q:'El ocho izquierdo presiona al lateral. Toca adónde va el ocho del lado lejano para mantener la cobertura.',options:['Arriba, presionando al defensa central Azul','Cerrado, al lado de tu seis','Abierto, al lado de tu lateral derecho'],explain:'Cerrado al lado del seis, el ocho del lado lejano cubre el carril por dentro detrás de la presión.'},
   {q:'Azul cambia de juego a su lateral derecho. El diez sigue tapando a su seis. Arrastra a tu ocho derecho a su tarea.',options:['Cerrar al lateral derecho','Bajar al lado de tu seis','Presionar al seis Azul con el diez'],explain:'El diez mantiene la pantalla y el lateral derecho se queda con el extremo, así que el ocho derecho cierra al lateral.'}]},
 'exp11_wingbackcue':{title:'Línea de cinco: ¿cuándo sale el carrilero?',concept:'Un carrilero presiona solo cuando el control es lento y un defensa central cubre al extremo por detrás. Cuando esa señal desaparece, recupera.',
  steps:['Tu línea de cinco tiene dos carrileros por fuera de tres defensas centrales. El carrilero cercano y el central exterior tienen tareas distintas cuando el balón va a la banda.','Los tres mediocampistas protegen las rutas por dentro. Un carrilero puede presionar a un lateral solo si el central exterior puede cubrir al extremo por detrás.','El que recibe en la banda hace un control lento. Tu central exterior está en el lado del arco del extremo y el mediocampista cercano protege el pase por dentro. El carrilero tiene cobertura para acercarse.','El control es lento y el extremo está cubierto. ¿Qué movimiento usa ese apoyo?','El carrilero presiona desde dentro. El central exterior se queda con el extremo y el mediocampista cercano cubre el carril por dentro detrás de la presión.','Ahora el lateral rival mira hacia delante y conduce más allá de la presión. El extremo corre por detrás mientras un rival que corre por dentro ocupa a tu central exterior. La señal para presionar ya desapareció.','El extremo corre por detrás y tu defensa exterior tiene a un rival que corre por dentro. ¿Cuál es tu siguiente tarea?','El carrilero recupera por el lado del arco del que corre por la banda. El central exterior se encarga del que corre por dentro y el mediocampista cercano recupera hacia el rival con el balón. Las tres tareas vuelven a estar repartidas.'],
  questions:[{q:'El control es lento y el extremo está cubierto. ¿Qué movimiento usa ese apoyo?',options:['Acercarte al lateral','Retroceder al lado del defensa central'],explain:'Llega mientras el rival todavía está controlando el balón. El central exterior y el mediocampista cercano protegen las rutas detrás de ti y por dentro.'},
   {q:'El extremo corre por detrás y tu defensa exterior tiene a un rival que corre por dentro. ¿Cuál es tu siguiente tarea?',options:['Volver a presionar al rival con el balón','Recuperar con el extremo'],explain:'Recupera por el lado del arco del que corre por la banda mientras el central exterior protege la amenaza por dentro. La línea de cinco tiene que volver a conectarse antes de otra presión.'},
   {q:'El lateral Azul hace un control lento. ¿Qué imagen le da cobertura a tu carrilero para presionar?',options:['El mediocampista cercano subió mucho','El central exterior cerca del extremo','El central exterior metido por dentro'],explain:'El defensa central está en el lado del arco del extremo y el mediocampista cuida el centro, así que la presión está cubierta.'},
   {q:'El carrilero presiona al lateral. Toca dónde se queda el central exterior.',options:['En el lado del arco del extremo Azul','Metido al lado del defensa central','Arriba por la banda, detrás del carrilero'],explain:'El central exterior se queda con el extremo, así que el carrilero que presiona tiene cobertura detrás.'},
   {q:'Ahora el lateral derecho Azul hace un control lento, y tu central derecho se queda con el extremo. Arrastra a tu carrilero.',options:['Acercarse al lateral desde dentro','Quedarse atrás cerca de tu arco','Meterse en el mediocampo'],explain:'El control es lento y el extremo está cubierto, así que el carrilero puede presionar desde dentro.'}]},
 'exp11_droppingnine':{title:'Línea de cuatro y el seis: el nueve que baja',concept:'Cuando su delantero centro baja, tu seis se encarga de él para que los defensas centrales mantengan la línea. Si el seis está ocupado, un defensa central sale con cobertura.',
  steps:['Tu línea de cuatro protege la profundidad contra los tres delanteros adelantados del equipo Azul. Un delantero que baja y se aleja de esta línea puede cambiar quién debería defenderlo.','El seis es tu mediocampista de contención, delante de los defensas centrales. Si puede encargarse del delantero que baja, el defensa central cercano puede mantener conectada la línea.','El nueve baja delante de tu seis, que está libre para encargarse de ese receptor. Los dos extremos siguen arriba contra tus laterales, así que la línea de cuatro todavía tiene que proteger la profundidad.','El seis puede encargarse del nueve que baja. ¿Qué movimiento protege la línea defensiva?','El defensa central mantiene la línea mientras el seis se acerca al delantero que baja. Tu otro defensa central mantiene la profundidad en vez de quedarse solo por una persecución innecesaria.','Ahora el diez Azul ocupa a tu seis. El nueve cambia de lado y recibe detrás del mediocampista más cercano. Ese pase de responsabilidad de antes ya no es posible.','El nueve ha recibido y el seis está ocupado con el diez. ¿Qué debería hacer el defensa central más cercano?','El defensa central cercano se acerca al nueve con control. Su compañero baja para cubrir y el seis se queda con el diez. La presión y la cobertura cambian juntas.'],
  questions:[{q:'El seis puede encargarse del nueve que baja. ¿Qué movimiento protege la línea defensiva?',options:['Seguir al nueve hasta el mediocampo','Mantener conectada la línea defensiva'],explain:'El seis puede encargarse del delantero que baja. Seguir conectado protege la profundidad y deja tareas claras a tu compañero y a los laterales.'},
   {q:'El nueve ha recibido y el seis está ocupado con el diez. ¿Qué debería hacer el defensa central más cercano?',options:['Seguir retrocediendo hacia el arco','Salir con control y con cobertura'],explain:'Ahora eres el defensa disponible más cercano. Tu compañero baja, los laterales se cierran y el seis se queda con el diez mientras tú presionas al que recibe.'},
   {q:'El nueve Azul baja hacia el mediocampo. Toca dónde debería defender tu seis.',options:['Entre los defensas centrales','Cerca del nueve que baja','Afuera, hacia el diez Azul'],explain:'El seis se encarga del nueve que baja, así que los dos defensas centrales mantienen conectada la línea.'},
   {q:'El delantero baja y luego la imagen cambia. Ordena estos momentos, del primero al último.',options:['El nueve Azul baja por delante','El diez Azul ocupa a tu seis','El defensa central cercano sale con cobertura','Tu seis se encarga del nueve que baja'],explain:'Primero el seis se encarga del nueve, luego el diez bloquea ese pase de responsabilidad, así que sale el defensa central.'},
   {q:'Ahora el nueve recibe a la derecha, y el diez sigue ocupando a tu seis. Arrastra al defensa central derecho.',options:['Seguir retrocediendo hacia el arco','Salir al nueve con cobertura','Cerrarse al lado de su compañero'],explain:'El seis está ocupado con el diez, así que el defensa central cercano sale mientras su compañero cubre.'}]},
 'exp11_secondball':{title:'4-4-2: apoya la segunda jugada',concept:'Delanteros a dos alturas y un mediocampista por debajo ganan el balón suelto. Si lo gana el equipo Azul, recupera por el centro.',
  steps:['En este cuatro-cuatro-dos, los dos delanteros se colocan a alturas diferentes alrededor de la primera recepción. No deberían juntarse los dos en el mismo punto.','Cuatro mediocampistas apoyan por debajo de ellos. Un mediocampista central puede ir por el siguiente balón mientras el otro se queda más atrás; los mediocampistas de banda ofrecen ángulos diferentes.','Un primer toque disputado deja el balón suelto en el suelo. Los delanteros se mantienen a alturas diferentes, y el mediocampista cercano puede llegar por debajo de la disputa.','El balón sigue suelto por debajo de los delanteros. ¿Qué carrera le da a tu equipo apoyo para el siguiente toque?','El mediocampista cercano llega por debajo del balón suelto. Su compañero del centro se queda más atrás, listo para frenar un contraataque si Azul llega primero al siguiente toque.','Azul llega primero al siguiente toque y gira hacia tu arco. El balón ya no está suelto, así que tu mediocampista cercano tiene que pasar de apoyar a recuperar.','Ahora Azul controla el balón mirando hacia tu arco. ¿Qué protege a tu equipo ahora?','El mediocampista recupera por el centro al lado del compañero que cubre. Los mediocampistas de banda también vuelven, y los cuatro mediocampistas se conectan otra vez después del cambio de posesión.'],
  questions:[{q:'El balón sigue suelto por debajo de los delanteros. ¿Qué carrera le da a tu equipo apoyo para el siguiente toque?',options:['Llegar por debajo del balón suelto','Unirte arriba a los dos delanteros'],explain:'Así el siguiente que recibe tiene una opción cerca sin repetir lo que hacen los delanteros. Tu otro mediocampista central se queda más atrás por si el rival lo gana.'},
   {q:'Ahora Azul controla el balón mirando hacia tu arco. ¿Qué protege a tu equipo ahora?',options:['Perseguir el balón por detrás','Recuperar por el carril central'],explain:'Recuperar al lado del mediocampista que cubre vuelve a conectar el mediocampo con la línea de cuatro. Los delanteros pueden presionar el pase atrás desde detrás.'},
   {q:'El mediocampista cercano llega al balón suelto. Toca dónde debería quedarse su compañero del centro.',options:['Al lado del mediocampista en el balón','Más atrás, detrás del balón','Arriba con los dos delanteros'],explain:'Si se queda más atrás, el compañero puede frenar un contraataque si Azul llega primero al siguiente toque.'},
   {q:'Sigue la segunda jugada. Ordena estos momentos, del primero al último.',options:['Un toque disputado lo deja suelto','Azul lo gana, así que pasa a recuperar','Los delanteros se mantienen a alturas diferentes','El mediocampista cercano llega a apoyar'],explain:'Coloca las alturas, el balón queda suelto, llega el apoyo, y luego pasa a recuperar cuando Azul lo gana.'},
   {q:'¿Verdadero o falso? Aquí los dos mediocampistas centrales llegan al balón suelto, y tu equipo está protegido contra un contraataque.',options:['Falso','Verdadero'],explain:'Es falso. Un mediocampista tiene que quedarse más atrás, para que un contraataque Azul se encuentre con alguien que lo frene.'}]},
 'exp11_shortfreekick':{title:'Tiro libre en la banda: suelta la barrera a tiempo',concept:'En un tiro libre, la barrera espera a diez yardas (Regla 13). Cuando un tiro libre en corto se mueve, un jugador de la barrera presiona y todos los demás mantienen su tarea.',
  steps:['En este tiro libre desde la banda, tus dos jugadores de la barrera protegen la ruta directa del centro. Tienen que quedarse a la distancia obligatoria hasta que se cobre el tiro.','Cinco marcadores se quedan en el lado del arco de cinco rivales distintos que entran al área. Esas tareas siguen aunque Azul elija un tiro libre en corto.','Un jugador protege el borde del área, otro protege la opción corta por dentro, y uno de salida se queda más arriba. El portero organiza detrás de ellos.','El que cobra lo juega en corto y el balón se mueve claramente. El jugador de la barrera más cercano ya puede acercarse al que recibe, mientras el que cuida la opción corta mantiene cubierta la ruta por dentro.','El tiro libre en corto ya está en juego. Tu compañero protege la ruta por dentro. ¿Qué debería hacer el jugador de la barrera más cercano?','Un jugador de la barrera cierra al que recibe en corto. El otro protege la ruta original del centro, y el que cuida el centro se mantiene separado en vez de unirse a la misma presión.','El que recibe conduce hacia dentro, donde el que cuida la opción corta puede encargarse de él. El que cobró se mueve por fuera para recibir de vuelta, y eso crea otra tarea para el jugador de la barrera.','El que cuida el centro puede presionar al rival con el balón y el que cobró está disponible por fuera. ¿Qué tarea deberías tomar ahora?','El jugador de la barrera cubre el pase de vuelta por fuera mientras el que cuida el centro se acerca al rival con el balón. El que cuida el borde del área se queda por debajo de ellos, así que tres defensores mantienen tres tareas separadas.'],
  questions:[{q:'El tiro libre en corto ya está en juego. Tu compañero protege la ruta por dentro. ¿Qué debería hacer el jugador de la barrera más cercano?',options:['Cerrar al que recibe en corto','Quedarse en la línea de la barrera'],explain:'El balón se ha movido de forma legal y la antigua línea de la barrera ya no lo presiona. Acércate al que recibe mientras el que cuida la opción corta protege por dentro y los cinco marcadores siguen con sus rivales.'},
   {q:'El que cuida el centro puede presionar al rival con el balón y el que cobró está disponible por fuera. ¿Qué tarea deberías tomar ahora?',options:['Cubrir el pase de vuelta por fuera','Unirte a la presión por dentro'],explain:'Ahora tu compañero se encarga del rival con el balón. Tomar la ruta del pase de vuelta reparte las dos amenazas mientras el resto de la defensa del tiro libre sigue organizada.'},
   {q:'¿Verdadero o falso? Tus jugadores de la barrera pueden lanzarse sobre el que cobra antes de que se cobre el tiro libre.',options:['Falso','Verdadero'],explain:'Es falso. La barrera se queda a diez yardas (unos nueve metros) hasta que el balón se patea y se mueve claramente.'},
   {q:'Azul juega el tiro libre en corto. Ordena las tareas de tu barrera, de la primera a la última.',options:['El jugador de la barrera más cercano cierra al que recibe','El que cobra lo juega en corto y el balón se mueve','Un jugador de la barrera cubre el pase de vuelta por fuera','La barrera se queda a la distancia obligatoria'],explain:'Mantén la distancia, espera a que el balón se mueva, cierra al que recibe y luego cubre el pase de vuelta.'},
   {q:'Un jugador de la barrera cierra al que recibe en corto. El otro jugador de la barrera está oculto. Toca dónde se queda.',options:['Persiguiendo al que cobró','Uniéndose a la presión sobre el que recibe','Protegiendo la ruta del centro'],explain:'Un jugador de la barrera presiona y el otro protege la ruta del centro, así que cada tarea sigue cubierta.'}]},
};
